import type {
  CapabilityClientOptions,
  CapabilityExecutor,
  ApiResponse,
  ExecuteResponseData,
  StreamResponse,
  Logger,
  RateLimitErrorHook,
  CentralOptions,
} from './types';
import { ErrorCodes } from './types';
import {
  CapabilityError,
  CapabilityNotFoundError,
  ActionNotFoundError,
  NetworkError,
  ExecutionError,
  RateLimitError,
} from './errors';
import { FileUploader } from './uploader';
import { extractFiles, replaceFilesWithUrls } from './file-extractor';
import { slardar } from '@lark-apaas/internal-slardar';

// 方案文档 § Client SDK 改造伪代码原句：
//   `import capabilityMap from 'virtual:capabilities';  // build 时注入`
// 由 @lark-apaas/fullstack-vite-preset 的 capabilitiesBundlePlugin 在 dev/build 时
// 扫业务工程 server/capabilities/*.json 注入。类型声明在 ./virtual.d.ts。
import virtualCapabilitiesMap from 'virtual:capabilities';
import type { CapabilityConfig } from './types';

const LOG_PREFIX = '[CapabilityClient]';

const defaultLogger: Logger = {
  debug: console.debug.bind(console),
  info: console.info.bind(console),
  warn: console.warn.bind(console),
  error: console.error.bind(console),
};

/**
 * 能力客户端
 */
export class CapabilityClient {
  private options: CapabilityClientOptions;
  private baseURL: string;
  private logger: Logger;
  private onRateLimitError?: RateLimitErrorHook;
  private central?: CentralOptions;

  constructor(options: CapabilityClientOptions) {
    this.options = options;
    // 移除末尾的斜杠，确保拼接时格式正确
    this.baseURL = (options?.baseURL ?? '').replace(/\/+$/, '');
    this.logger = options?.logger ?? defaultLogger;
    this.onRateLimitError = options?.onRateLimitError;
    if (options?.central?.enabled) {
      this.central = options.central;
    }
  }

  /**
   * central.baseURL → caller 显式给的（去尾斜杠）。
   * 没传：浏览器取 `window.location.origin`（同源调用，SSO cookie 自动带）；
   *      非浏览器（SSR / Node.js 测试）抛错。
   * 用法与 fullstack-plugin/packages/client/dataloom/src/service/index.ts 一致。
   */
  private resolveCentralBaseURL(central: CentralOptions): string {
    if (central.baseURL) return central.baseURL.replace(/\/+$/, '');
    if (typeof window !== 'undefined' && window.location?.origin) {
      return window.location.origin;
    }
    throw new Error(
      'CapabilityClient: central.baseURL is required when running outside browser (window.location unavailable)',
    );
  }

  /**
   * 预览态 / 运行态自动判定。沿用 nestjs-capability/src/capability.module.ts:18 同款判定:
   *   - 沙箱 fullstack-cli scripts/dev.sh → `NODE_ENV=development` → 预览态
   *   - 运行态（npm start / build 后部署）→ `NODE_ENV=production` → 运行态
   * Vite 在构建时把 `process.env.NODE_ENV` 替换为字面量字符串。
   */
  private resolveMode(): 'preview' | 'runtime' {
    const env = typeof process !== 'undefined' ? process.env?.NODE_ENV : undefined;
    return env === 'development' ? 'preview' : 'runtime';
  }

  /**
   * 构造单次调用的请求 URL：
   *   - central 开启：4 个中心端点之一（mode 自动判定）；
   *   - central 关闭：保持原 `${baseURL}/api/capability/{id}` 行为。
   */
  private buildExecuteUrl(capabilityId: string, stream: boolean): string {
    if (!this.central) {
      return `${this.baseURL}/api/capability/${capabilityId}${stream ? '/stream' : ''}`;
    }
    const base = this.resolveCentralBaseURL(this.central);
    const segment = this.resolveMode() === 'preview' ? '/preview/execute' : '/execute';
    return `${base}/app/${this.central.appId}/__runtime__/api/v1/plugin_server/capability/${capabilityId}${segment}${stream ? '/stream' : ''}`;
  }

  /**
   * 构造请求体：
   *   - central + 预览态：`{ capability, action, params }`，capability 取自
   *     `virtual:capabilities`（load() 时已经 fail-fast 校验过，这里直接取）。
   *   - central + 运行态：`{ action, params }`（中心服务通过 RPC 查中心存储拿 config）。
   *   - 非 central：`{ action, params }`。
   */
  private buildRequestBody(
    capabilityId: string,
    action: string,
    params: Record<string, unknown>,
  ): string {
    if (this.central && this.resolveMode() === 'preview') {
      const capability = virtualCapabilitiesMap[capabilityId] as CapabilityConfig | undefined;
      if (!capability) {
        // 理论上 load() 已经 fail-fast 校验，但兜底处理
        throw new CapabilityNotFoundError(capabilityId);
      }
      return JSON.stringify({ capability, action, params });
    }
    return JSON.stringify({ action, params });
  }

  /**
   * 加载能力，返回执行器。
   * 方案文档 § Client SDK 改造伪代码：
   *   const config = capabilityMap[id];
   *   if (!config) throw new CapabilityNotFoundError(id);
   * central + 预览态时 fail-fast：本地 `virtual:capabilities` map 没这个 id 就直接抛，
   * 不发任何网络请求。运行态 / 非 central 模式跳过此校验。
   */
  load(capabilityId: string): CapabilityExecutor {
    if (this.central && this.resolveMode() === 'preview') {
      if (!(capabilityId in virtualCapabilitiesMap)) {
        throw new CapabilityNotFoundError(capabilityId);
      }
    }
    return this.createExecutor(capabilityId);
  }

  private createExecutor(capabilityId: string): CapabilityExecutor {
    return {
      call: <T = unknown>(action: string, params?: Record<string, unknown>) => {
        return this.executeCall<T>(capabilityId, action, params);
      },
      callStream: <T = unknown>(action: string, params?: Record<string, unknown>) => {
        return this.executeCallStream<T>(capabilityId, action, params);
      },
    };
  }

  private async executeCall<T>(
    capabilityId: string,
    action: string,
    params?: Record<string, unknown>
  ): Promise<T> {
    const url = this.buildExecuteUrl(capabilityId, false);
    let requestParams = params ?? {};

    // 处理文件上传
    const extractedFiles = extractFiles(requestParams);
    if (extractedFiles.length > 0) {
      this.logger.info(LOG_PREFIX, `uploading ${extractedFiles.length} file(s)...`);
      const uploader = new FileUploader(this.options);
      const uploadResults = await uploader.uploadAll(extractedFiles);
      requestParams = replaceFilesWithUrls(requestParams, uploadResults);
      this.logger.info(LOG_PREFIX, `file upload completed`);
    }

    this.logger.info(LOG_PREFIX, `call start: capabilityId=${capabilityId}, action=${action}`, { params: requestParams });

    try {
      const response = await fetch(url, {
        method: 'POST',
        ...this.options.fetchOptions,
        headers: {
          'Content-Type': 'application/json',
          ...this.options.fetchOptions?.headers,
        },
        body: this.buildRequestBody(capabilityId, action, requestParams),
      });

      const data = (await response.json()) as ApiResponse<ExecuteResponseData>;

      if (!response.ok || data.status_code !== ErrorCodes.SUCCESS) {
        const errorResponse = data as {
          status_code: string;
          error_msg: string;
          is_rate_limit_error?: boolean;
        };
        const errorCode = errorResponse.status_code;

        // 计费受限错误：通过 is_rate_limit_error 字段识别
        if (errorResponse.is_rate_limit_error) {
          const rateLimitError = new RateLimitError(
            errorCode,  // status_code 就是业务错误码
            errorResponse.error_msg,
            response.status,
          );
          await this.onRateLimitError?.(rateLimitError);
          throw rateLimitError;
        }

        switch (errorCode) {
          case ErrorCodes.CAPABILITY_NOT_FOUND:
            throw new CapabilityNotFoundError(capabilityId, response.status);
          case ErrorCodes.ACTION_NOT_FOUND:
            throw new ActionNotFoundError(errorResponse.error_msg, response.status);
          case ErrorCodes.PLUGIN_NOT_FOUND:
          case ErrorCodes.EXECUTION_ERROR:
          default:
            throw new ExecutionError(errorResponse.error_msg, response.status);
        }
      }

      const result = (data as { data: ExecuteResponseData }).data.output as T;

      this.logger.info(LOG_PREFIX, `call success: capabilityId=${capabilityId}, action=${action}`, { result });

      return result;
    } catch (error) {
      this.logger.error(LOG_PREFIX, `call failed: capabilityId=${capabilityId}, action=${action}`, { params: requestParams, error });
      slardar.captureException(error, { source: 'client-capability', module: 'execute-call', capabilityId, action });
      if (error instanceof CapabilityError) {
        throw error;
      }
      throw new NetworkError(error instanceof Error ? error.message : String(error));
    }
  }

  private async *executeCallStream<T>(
    capabilityId: string,
    action: string,
    params?: Record<string, unknown>
  ): AsyncIterable<T> {
    const url = this.buildExecuteUrl(capabilityId, true);
    let requestParams = params ?? {};

    // 处理文件上传
    const extractedFiles = extractFiles(requestParams);
    if (extractedFiles.length > 0) {
      this.logger.info(LOG_PREFIX, `uploading ${extractedFiles.length} file(s)...`);
      const uploader = new FileUploader(this.options);
      const uploadResults = await uploader.uploadAll(extractedFiles);
      requestParams = replaceFilesWithUrls(requestParams, uploadResults);
      this.logger.info(LOG_PREFIX, `file upload completed`);
    }

    this.logger.info(LOG_PREFIX, `callStream start: capabilityId=${capabilityId}, action=${action}`, { params: requestParams });

    // central + preview 模式下 buildRequestBody 可能抛 CapabilityNotFoundError，
    // 先于 fetch 计算好 body，避免被下面的 NetworkError 包装吞掉类型。
    const body = this.buildRequestBody(capabilityId, action, requestParams);

    let response: Response;
    try {
      response = await fetch(url, {
        method: 'POST',
        ...this.options.fetchOptions,
        headers: {
          'Content-Type': 'application/json',
          ...this.options.fetchOptions?.headers,
        },
        body,
      });
    } catch (error) {
      this.logger.error(LOG_PREFIX, `callStream failed: capabilityId=${capabilityId}, action=${action}`, { params: requestParams, error });
      slardar.captureException(error, { source: 'client-capability', module: 'execute-call-stream', capabilityId, action, phase: 'fetch' });
      throw new NetworkError(error instanceof Error ? error.message : String(error));
    }

    if (!response.ok) {
      const errMsg = `HTTP ${response.status} ${response.statusText}`;
      this.logger.error(LOG_PREFIX, `callStream failed: capabilityId=${capabilityId}, action=${action}`, { params: requestParams, error: errMsg });
      throw new NetworkError(errMsg);
    }

    if (!response.body) {
      const errMsg = 'Response body is null';
      this.logger.error(LOG_PREFIX, `callStream failed: capabilityId=${capabilityId}, action=${action}`, { params: requestParams, error: errMsg });
      throw new NetworkError(errMsg);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let chunkCount = 0;
    let aggregatedContent = '';
    let canAggregate = true;

    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6);

            try {
              const parsed = JSON.parse(data) as StreamResponse;

              if (parsed.status_code === ErrorCodes.SUCCESS && parsed.data) {
                if (parsed.data.type === 'content') {
                  chunkCount++;
                  const delta = parsed.data.delta as T;

                  // 尝试聚合 content 字段
                  if (canAggregate) {
                    const content = (delta as Record<string, unknown>)?.content;
                    if (typeof content === 'string') {
                      aggregatedContent += content;
                    } else {
                      canAggregate = false;
                    }
                  }

                  yield delta;

                  if (parsed.data.finished) {
                    const resultInfo = canAggregate
                      ? { chunkCount, result: aggregatedContent }
                      : { chunkCount, resultLength: aggregatedContent.length || chunkCount };
                    this.logger.info(LOG_PREFIX, `callStream end: capabilityId=${capabilityId}, action=${action}`, resultInfo);
                    return;
                  }
                } else if (parsed.data.type === 'error') {
                  const err = parsed.data.error;
                  if (err.isRateLimitError) {
                    const rateLimitError = new RateLimitError(
                      err.code,  // code 就是业务错误码
                      err.message,
                    );
                    await this.onRateLimitError?.(rateLimitError);
                    throw rateLimitError;
                  }
                  throw new ExecutionError(err.message);
                }
              }
            } catch (parseError) {
              if (parseError instanceof CapabilityError) {
                this.logger.error(LOG_PREFIX, `callStream failed: capabilityId=${capabilityId}, action=${action}`, { params: requestParams, error: parseError, chunkCount });
                throw parseError;
              }
              // 忽略非 JSON 行
            }
          }
        }
      }
      const resultInfo = canAggregate
        ? { chunkCount, result: aggregatedContent }
        : { chunkCount, resultLength: aggregatedContent.length || chunkCount };
      this.logger.info(LOG_PREFIX, `callStream end: capabilityId=${capabilityId}, action=${action}`, resultInfo);
    } catch (error) {
      this.logger.error(LOG_PREFIX, `callStream failed: capabilityId=${capabilityId}, action=${action}`, { params: requestParams, error, chunkCount });
      slardar.captureException(error, { source: 'client-capability', module: 'execute-call-stream', capabilityId, action, phase: 'read' });
      if (error instanceof CapabilityError) {
        throw error;
      }
      throw new NetworkError(error instanceof Error ? error.message : String(error));
    } finally {
      reader.releaseLock();
    }
  }
}

/**
 * 创建客户端实例
 */
export function createClient(options: CapabilityClientOptions): CapabilityClient {
  return new CapabilityClient(options);
}
