import type { RateLimitError } from './errors';

/**
 * Logger 接口，兼容 console 和 @lark-apaas/toolkit 的 logger
 */
export interface Logger {
  debug(message: unknown, ...args: unknown[]): void;
  info(message: unknown, ...args: unknown[]): void;
  warn(message: unknown, ...args: unknown[]): void;
  error(message: unknown, ...args: unknown[]): void;
}

/**
 * RateLimitError 钩子函数类型
 * 当检测到计费受限错误时，在抛出异常前调用此钩子
 */
export type RateLimitErrorHook = (error: RateLimitError) => void | Promise<void>;

/**
 * 客户端配置选项
 */
export interface CapabilityClientOptions {
  /** 全局路径前缀，默认 ''。例如线上环境可设置为 '/spark/a' */
  baseURL?: string;
  /** 获取文件上传预签名 URL 的接口地址，由上层注入 */
  acquireUploadUrl: string;
  /** 获取文件临时下载 URL 的接口地址，由上层注入 */
  acquireDownloadUrl: string;
  /** 自定义 fetch 配置 */
  fetchOptions?: RequestInit;
  /** 自定义 logger，默认使用 console */
  logger?: Logger;
  /**
   * 计费受限错误钩子
   * 当检测到 RateLimitError 时，在抛出异常前调用此钩子
   * 可用于上报埋点、展示 toast 等场景
   */
  onRateLimitError?: RateLimitErrorHook;
  /**
   * 中心化服务分流开关。启用后 capability 调用路由到妙搭 plugin_server 的 4 个中心端点：
   *   - 运行态 非流式: POST {baseURL}/app/{appId}/__runtime__/api/v1/plugin_server/capability/{capabilityId}/execute
   *   - 运行态 流式:   POST {baseURL}/app/{appId}/__runtime__/api/v1/plugin_server/capability/{capabilityId}/execute/stream
   *   - 预览态 非流式: POST {baseURL}/app/{appId}/__runtime__/api/v1/plugin_server/capability/{capabilityId}/preview/execute
   *   - 预览态 流式:   POST {baseURL}/app/{appId}/__runtime__/api/v1/plugin_server/capability/{capabilityId}/preview/execute/stream
   *
   * baseURL 默认取 `window.location.origin`（同源调用，SSO cookie 自动带）。
   * 预览态 / 运行态由 `process.env.NODE_ENV` 自动判定：
   *   - 沙箱开发态（fullstack-cli scripts/dev.sh 起的进程，NODE_ENV=development）→ 预览态
   *   - 运行态启动（NODE_ENV=production，无论 build 还是 npm start）→ 运行态
   * 业务前端 `createClient` 配置不需要区分两种环境。
   *
   * 预览态 body 必须携带完整 capability config，从 `capabilities` map 查；缺失抛
   * CapabilityNotFoundError。运行态由中心服务通过 capability_id 走 RPC 查中心存储。
   */
  central?: CentralOptions;
}

/**
 * 中心化服务分流配置。
 */
export interface CentralOptions {
  /** 是否启用中心化分流；false / 未配置则维持原行为打用户应用。 */
  enabled: boolean;
  /**
   * 中心服务 base URL（含 scheme）。可选；不传时默认 `window.location.origin`。
   * 非浏览器环境（SSR / Node.js 测试）必须显式传，否则 SDK 抛错。
   */
  baseURL?: string;
  /** 当前应用 ID，拼接在 `/app/{appId}/__runtime__/...` 路径段。 */
  appId: string;
}

/**
 * Capability 配置，与 @lark-apaas/nestjs-capability / miaoda_plugin_server 的 interfaces/capability-config.ts 对齐。
 * 预览态 body.capability 必须为完整对象。
 */
export interface CapabilityConfig {
  id: string;
  pluginKey: string;
  pluginVersion: string;
  name: string;
  description: string;
  paramsSchema: unknown;
  formValue: Record<string, unknown>;
  createdAt: number;
  updatedAt: number;
}

/**
 * 能力执行器接口
 */
export interface CapabilityExecutor {
  /**
   * 调用能力
   * @param action - Action 名称
   * @param params - 输入参数
   * @returns Action 执行结果
   */
  call<T = unknown>(
    action: string,
    params?: Record<string, unknown>
  ): Promise<T>;

  /**
   * 流式调用能力
   * @param action - Action 名称
   * @param params - 输入参数
   * @returns AsyncIterable，逐个 yield chunk
   */
  callStream<T = unknown>(
    action: string,
    params?: Record<string, unknown>
  ): AsyncIterable<T>;
}

// ========== API 响应类型 ==========

/**
 * 成功响应
 */
export interface SuccessResponse<T> {
  status_code: '0';
  data: T;
}

/**
 * 错误响应
 */
export interface ErrorResponse {
  status_code: string;
  error_msg: string;
  /** 是否为计费受限错误 */
  is_rate_limit_error?: boolean;
}

/**
 * API 响应类型
 */
export type ApiResponse<T> = SuccessResponse<T> | ErrorResponse;

// ========== 具体响应 data 结构 ==========

/**
 * 执行接口响应 data 结构
 */
export interface ExecuteResponseData {
  output: unknown;
}

// ========== 流式响应结构 ==========

/**
 * 流式内容响应
 */
export interface StreamContentResponse {
  status_code: '0';
  data: {
    type: 'content';
    delta: unknown;
    finished?: boolean;
  };
}

/**
 * 流式错误响应
 */
export interface StreamErrorResponse {
  status_code: '0';
  data: {
    type: 'error';
    error: {
      /** 错误码，计费受限时为业务错误码（如 k_st_ec_400002687） */
      code: string;
      message: string;
      /** 是否为计费受限错误 */
      isRateLimitError?: boolean;
    };
  };
}

/**
 * 流式响应类型
 */
export type StreamResponse = StreamContentResponse | StreamErrorResponse;

// ========== 错误码 ==========

/**
 * 后端错误码
 */
export const ErrorCodes = {
  SUCCESS: '0',
  CAPABILITY_NOT_FOUND: 'k_ec_cap_001',
  PLUGIN_NOT_FOUND: 'k_ec_cap_002',
  ACTION_NOT_FOUND: 'k_ec_cap_003',
  PARAMS_VALIDATION_ERROR: 'k_ec_cap_004',
  EXECUTION_ERROR: 'k_ec_cap_005',
  RATE_LIMIT_EXCEEDED: 'k_ec_cap_006',
} as const;

// ========== 文件上传相关类型 ==========

/**
 * 提取的文件信息
 */
export interface ExtractedFile {
  /** 在 params 中的路径，如 ['image_list', 0] */
  path: (string | number)[];
  /** 文件对象 */
  file: File | Blob;
}

/**
 * 上传结果
 */
export interface UploadResult {
  /** 在 params 中的路径 */
  path: (string | number)[];
  /** 临时下载 URL */
  downloadUrl: string;
}

/**
 * 获取上传 URL 响应
 */
export interface AcquireUploadUrlResponse {
  status_code: string;
  data: {
    uploadURL: string;
    objectKey: string;
  };
}

/**
 * 获取下载 URL 响应
 */
export interface AcquireDownloadUrlResponse {
  status_code: string;
  data: {
    downloadURL: string;
  };
}
