import type { ExtractedFile, UploadResult } from './types';

/**
 * 检测是否为 File 或 Blob
 */
export function isFile(value: unknown): value is File | Blob {
  return value instanceof File || value instanceof Blob;
}

/**
 * 递归提取 params 中的所有文件
 *
 * @example
 * extractFiles({ image_list: [file1, file2] })
 * // => [
 * //   { path: ['image_list', 0], file: file1 },
 * //   { path: ['image_list', 1], file: file2 }
 * // ]
 */
export function extractFiles(params: Record<string, unknown>): ExtractedFile[] {
  const files: ExtractedFile[] = [];

  function traverse(obj: unknown, path: (string | number)[]): void {
    if (isFile(obj)) {
      files.push({ path: [...path], file: obj });
    } else if (Array.isArray(obj)) {
      obj.forEach((item, index) => traverse(item, [...path, index]));
    } else if (obj !== null && typeof obj === 'object') {
      Object.entries(obj).forEach(([key, value]) => {
        traverse(value, [...path, key]);
      });
    }
  }

  traverse(params, []);
  return files;
}

/**
 * 根据上传结果替换 params 中的文件为 URL
 *
 * @example
 * replaceFilesWithUrls(
 *   { image_list: [file1, file2] },
 *   [
 *     { path: ['image_list', 0], downloadUrl: 'https://...' },
 *     { path: ['image_list', 1], downloadUrl: 'https://...' }
 *   ]
 * )
 * // => { image_list: ['https://...', 'https://...'] }
 */
export function replaceFilesWithUrls(
  params: Record<string, unknown>,
  results: UploadResult[]
): Record<string, unknown> {
  // 创建 path -> url 的映射，用于快速查找
  const urlMap = new Map<string, string>();
  for (const { path, downloadUrl } of results) {
    urlMap.set(JSON.stringify(path), downloadUrl);
  }

  // 手动深拷贝，同时将 File/Blob 替换为对应的 URL
  // 注意：不能使用 structuredClone，因为它不支持 File/Blob 对象
  function cloneAndReplace(obj: unknown, currentPath: (string | number)[]): unknown {
    // 检查当前路径是否有对应的 URL
    const pathKey = JSON.stringify(currentPath);
    if (urlMap.has(pathKey)) {
      return urlMap.get(pathKey);
    }

    // 如果是 File/Blob 但没有对应的 URL（不应该发生），返回 null
    if (isFile(obj)) {
      return null;
    }

    if (Array.isArray(obj)) {
      return obj.map((item, index) => cloneAndReplace(item, [...currentPath, index]));
    }

    if (obj !== null && typeof obj === 'object') {
      const result: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(obj)) {
        result[key] = cloneAndReplace(value, [...currentPath, key]);
      }
      return result;
    }

    // 原始值直接返回
    return obj;
  }

  return cloneAndReplace(params, []) as Record<string, unknown>;
}
