import type {
  CapabilityClientOptions,
  ExtractedFile,
  UploadResult,
  AcquireUploadUrlResponse,
  AcquireDownloadUrlResponse,
} from './types';
import { FileUploadError } from './errors';
import { slardar } from '@lark-apaas/internal-slardar';

type FileUploaderOptions = Pick<CapabilityClientOptions, 'acquireUploadUrl' | 'acquireDownloadUrl' | 'fetchOptions'>;

/**
 * 文件上传器
 */
export class FileUploader {
  private readonly options: FileUploaderOptions;

  constructor(options: FileUploaderOptions) {
    this.options = options;
  }

  /**
   * 上传单个文件，返回下载 URL
   */
  async upload(file: File | Blob): Promise<string> {
    const fileName = file instanceof File ? file.name : `blob-${Date.now()}`;

    // 1. 获取上传预签名 URL
    const { uploadURL, objectKey } = await this.fetchUploadUrl(fileName);

    // 2. 上传文件到 TOS
    await this.uploadToTos(uploadURL, file);

    // 3. 获取下载 URL
    const downloadUrl = await this.fetchDownloadUrl(objectKey);

    return downloadUrl;
  }

  /**
   * 并发上传多个文件
   */
  async uploadAll(files: ExtractedFile[]): Promise<UploadResult[]> {
    const results = await Promise.all(
      files.map(async ({ path, file }) => {
        const downloadUrl = await this.upload(file);
        return { path, downloadUrl };
      })
    );
    return results;
  }

  /**
   * 获取上传预签名 URL
   */
  private async fetchUploadUrl(fileName: string): Promise<{ uploadURL: string; objectKey: string }> {
    const { acquireUploadUrl, fetchOptions } = this.options;

    let response: Response;
    try {
      response = await fetch(acquireUploadUrl, {
        method: 'POST',
        ...fetchOptions,
        headers: {
          'Content-Type': 'application/json',
          ...fetchOptions?.headers,
        },
        body: JSON.stringify({ fileName }),
      });
    } catch (error) {
      slardar.captureException(error, { source: 'client-capability', module: 'file-upload', step: 'fetch-upload-url' });
      throw new FileUploadError(
        `Failed to acquire upload URL: ${error instanceof Error ? error.message : String(error)}`
      );
    }

    if (!response.ok) {
      throw new FileUploadError(
        `Failed to acquire upload URL: HTTP ${response.status}`,
        response.status
      );
    }

    const data = (await response.json()) as AcquireUploadUrlResponse;

    if (data.status_code !== '0') {
      throw new FileUploadError(`Failed to acquire upload URL: ${data.status_code}`);
    }

    return data.data;
  }

  /**
   * 上传文件到 TOS（预签名 URL）
   */
  private async uploadToTos(uploadURL: string, file: File | Blob): Promise<void> {
    let response: Response;
    try {
      response = await fetch(uploadURL, {
        method: 'PUT',
        body: file,
      });
    } catch (error) {
      slardar.captureException(error, { source: 'client-capability', module: 'file-upload', step: 'upload-to-tos' });
      throw new FileUploadError(
        `Failed to upload file to TOS: ${error instanceof Error ? error.message : String(error)}`
      );
    }

    if (!response.ok) {
      throw new FileUploadError(
        `Failed to upload file to TOS: HTTP ${response.status}`,
        response.status
      );
    }
  }

  /**
   * 获取临时下载 URL
   */
  private async fetchDownloadUrl(objectKey: string): Promise<string> {
    const { acquireDownloadUrl, fetchOptions } = this.options;

    let response: Response;
    try {
      response = await fetch(acquireDownloadUrl, {
        method: 'POST',
        ...fetchOptions,
        headers: {
          'Content-Type': 'application/json',
          ...fetchOptions?.headers,
        },
        body: JSON.stringify({ objectKey }),
      });
    } catch (error) {
      slardar.captureException(error, { source: 'client-capability', module: 'file-upload', step: 'fetch-download-url' });
      throw new FileUploadError(
        `Failed to acquire download URL: ${error instanceof Error ? error.message : String(error)}`
      );
    }

    if (!response.ok) {
      throw new FileUploadError(
        `Failed to acquire download URL: HTTP ${response.status}`,
        response.status
      );
    }

    const data = (await response.json()) as AcquireDownloadUrlResponse;

    if (data.status_code !== '0') {
      throw new FileUploadError(`Failed to acquire download URL: ${data.status_code}`);
    }

    return data.data.downloadURL;
  }
}
