/**
 * 能力调用错误基类
 */
export class CapabilityError extends Error {
  /** 错误码 */
  code: string;
  /** HTTP 状态码 */
  statusCode?: number;

  constructor(message: string, code: string, statusCode?: number) {
    super(message);
    this.name = 'CapabilityError';
    this.code = code;
    this.statusCode = statusCode;
  }
}

/**
 * 能力不存在错误
 */
export class CapabilityNotFoundError extends CapabilityError {
  constructor(capabilityId: string, statusCode?: number) {
    super(`Capability not found: ${capabilityId}`, 'CAPABILITY_NOT_FOUND', statusCode);
    this.name = 'CapabilityNotFoundError';
  }
}

/**
 * Action 不存在错误
 */
export class ActionNotFoundError extends CapabilityError {
  constructor(message: string, statusCode?: number) {
    super(message, 'ACTION_NOT_FOUND', statusCode);
    this.name = 'ActionNotFoundError';
  }
}

/**
 * 网络错误
 */
export class NetworkError extends CapabilityError {
  constructor(message: string) {
    super(message, 'NETWORK_ERROR');
    this.name = 'NetworkError';
  }
}

/**
 * 执行错误
 */
export class ExecutionError extends CapabilityError {
  constructor(message: string, statusCode?: number) {
    super(message, 'EXECUTION_ERROR', statusCode);
    this.name = 'ExecutionError';
  }
}

/**
 * 文件上传错误
 */
export class FileUploadError extends CapabilityError {
  constructor(message: string, statusCode?: number) {
    super(message, 'FILE_UPLOAD_ERROR', statusCode);
    this.name = 'FileUploadError';
  }
}

/**
 * 计费受限错误
 */
export class RateLimitError extends CapabilityError {
  /** 业务错误码 */
  rateLimitCode: string;
  /** 业务错误消息 */
  rateLimitMessage: string;

  constructor(rateLimitCode: string, rateLimitMessage: string, statusCode?: number) {
    super(rateLimitMessage, 'RATE_LIMIT_EXCEEDED', statusCode);
    this.name = 'RateLimitError';
    this.rateLimitCode = rateLimitCode;
    this.rateLimitMessage = rateLimitMessage;
  }
}
